import{_ as a,o as n,c as s,ah as i}from"./chunks/framework.BsNNkeaH.js";const m=JSON.parse('{"title":"Era Admission","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"admission/index.md","filePath":"src/admission/index.md"}'),t={name:"admission/index.md"};function r(o,e,d,l,p,c){return n(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="era-admission" tabindex="-1">Era Admission <a class="header-anchor" href="#era-admission" aria-label="Permalink to &quot;Era Admission&quot;">​</a></h1><p>Era Admission est le canal par lequel une école découvre et adopte ERA avant, éventuellement, de gérer son propre serveur. Ce n&#39;est pas le quotidien d&#39;un établissement déjà équipé — pour ça, voir le <a href="/guide/">guide par rôle</a>.</p><p>Deux publics bien distincts se croisent ici :</p><ul><li><strong><a href="/admission/ecoles/inscription-et-demo.html">Les écoles</a></strong> — une école qui découvre ERA s&#39;inscrit gratuitement en ligne, peut activer une démonstration complète pendant une durée limitée, puis passer à une licence payante (à la carte, par pôle) accompagnée par l&#39;équipe edPage.</li><li><strong><a href="/admission/staff-edpage/">L&#39;équipe edPage</a></strong> — le personnel commercial/support edPage dispose d&#39;un panneau interne séparé pour gérer les établissements inscrits : accorder une licence, clore une démonstration, purger un compte expiré.</li></ul><p>Ces deux parcours n&#39;ont rien à voir avec les comptes utilisateurs d&#39;un établissement (rôles admin, enseignant, etc.) : ils se déroulent sur le domaine central d&#39;ERA, avant même qu&#39;un compte d&#39;établissement existe.</p>',5)])])}const _=a(t,[["render",r]]);export{m as __pageData,_ as default};
